def lookup_order_id(customer_name):
    # decomposing the goal into steps
    return "A100" if customer_name == "Alice" else None

def lookup_shipping_status(order_id):
    # ordering matters when steps depend on each other
    return "shipped" if order_id == "A100" else "unknown"

def build_plan(goal):
    # decomposing the goal into steps
    return [
        {"step": "lookup_order_id", "depends_on": None},
        {"step": "lookup_shipping_status", "depends_on": "lookup_order_id"},
    ]

def execute_plan(plan, customer_name):
    results = {}
    for step in plan:
        if step["step"] == "lookup_order_id":
            results["lookup_order_id"] = lookup_order_id(customer_name)
        elif step["step"] == "lookup_shipping_status":
            order_id = results.get(step["depends_on"])
            results["lookup_shipping_status"] = lookup_shipping_status(order_id)
    return results

goal = "Find the shipping status of Alice's order"
plan = build_plan(goal)
results = execute_plan(plan, "Alice")

print("Planned steps:")
for step in plan:
    print(f" {step}")
print("\nExecution results:")
print(results)
